import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const TRANSITION = 12;

const COLORS = {
  teal: "#00D4AA",
  tealDim: "rgba(0,212,170,0.15)",
  blue: "#4A9EFF",
  purple: "#9B59B6",
  orange: "#FF6B2B",
  orangeLight: "#FFB347",
  red: "#FF5C5C",
  bg: "#0E0E14",
  surface: "rgba(255,255,255,0.04)",
  border: "rgba(255,255,255,0.08)",
  text: "#FFFFFF",
  muted: "rgba(255,255,255,0.45)",
};

// ─── Scene 1 ───────────────────────────────────────────────────────────────
// "Beyond just tracking numbers, the data"
// Raw chaotic numbers → structured rows crystallising
// ─────────────────────────────────────────────────────────────────────────

const CHAOS_NUMBERS = [
  "1,240,000", "48.2K", "2024-03-15", "TechReviewHub", "93%",
  "327", "4.8★", "00:12:44", "#headphones", "USD 349",
  "892K", "21.4K", "2024-01-08", "GadgetGuru", "87%",
  "214", "4.5★", "00:08:21", "#audio", "USD 279",
];

const STRUCTURED_ROWS = [
  { key: "title",     value: "Best noise-cancelling headphones 2024", color: COLORS.text },
  { key: "channel",   value: "TechReviewHub",                        color: COLORS.teal },
  { key: "views",     value: "1,240,000",                            color: COLORS.blue },
  { key: "likes",     value: "48,200",                               color: COLORS.purple },
  { key: "published", value: "2024-03-15",                           color: COLORS.orangeLight },
];

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Phase: chaos fades out at frame 28, structured rows fade in from 30
  const chaosOpacity = interpolate(frame, [0, 10, 38, 48], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const structuredOpacity = interpolate(frame, [38, 52], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const titleProgress = spring({ frame: frame - 40, fps, delay: 0, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>

      {/* Chaos layer */}
      <AbsoluteFill style={{ opacity: chaosOpacity }}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            flexWrap: "wrap",
            alignContent: "center",
            justifyContent: "center",
            gap: 48,
            padding: "200px 300px",
          }}
        >
          {CHAOS_NUMBERS.map((num, i) => {
            const drift = interpolate(frame, [0, 48], [0, (i % 3 - 1) * 18], {
              extrapolateRight: "clamp",
            });
            const flicker = Math.sin(frame * 0.4 + i * 1.7) * 0.3 + 0.5;
            return (
              <div
                key={i}
                style={{
                  fontSize: 32 + (i % 4) * 10,
                  fontWeight: 700,
                  color: i % 3 === 0 ? COLORS.teal : i % 3 === 1 ? COLORS.blue : COLORS.muted,
                  opacity: flicker,
                  transform: `translateY(${drift}px)`,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                {num}
              </div>
            );
          })}
        </div>
      </AbsoluteFill>

      {/* Structured rows crystallising */}
      <AbsoluteFill style={{ opacity: structuredOpacity }}>
        <AbsoluteFill
          style={{
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            gap: 0,
            paddingBottom: 80,
          }}
        >
          {/* Label above */}
          <div
            style={{
              opacity: titleProgress,
              transform: `translateY(${interpolate(titleProgress, [0, 1], [-24, 0])}px)`,
              fontSize: 24,
              fontWeight: 700,
              color: COLORS.muted,
              letterSpacing: "0.16em",
              textTransform: "uppercase",
              marginBottom: 40,
            }}
          >
            Structured Data
          </div>

          {/* Rows */}
          <div
            style={{
              backgroundColor: COLORS.surface,
              borderRadius: 28,
              border: `1.5px solid ${COLORS.border}`,
              overflow: "hidden",
              minWidth: 900,
            }}
          >
            {STRUCTURED_ROWS.map((row, i) => {
              const rp = spring({ frame: frame - 40, fps, delay: i * 14, config: { damping: 200 } });
              return (
                <div
                  key={i}
                  style={{
                    display: "flex",
                    flexDirection: "row",
                    alignItems: "center",
                    gap: 0,
                    opacity: rp,
                    transform: `translateX(${interpolate(rp, [0, 1], [50, 0])}px)`,
                    borderBottom: i < STRUCTURED_ROWS.length - 1
                      ? `1px solid ${COLORS.border}`
                      : "none",
                  }}
                >
                  {/* Key column */}
                  <div
                    style={{
                      width: 220,
                      padding: "28px 36px",
                      fontSize: 26,
                      fontWeight: 700,
                      color: COLORS.muted,
                      textTransform: "uppercase",
                      letterSpacing: "0.08em",
                      borderRight: `1px solid ${COLORS.border}`,
                      flexShrink: 0,
                    }}
                  >
                    {row.key}
                  </div>
                  {/* Animated typing value */}
                  <div
                    style={{
                      padding: "28px 40px",
                      fontSize: 30,
                      fontWeight: 600,
                      color: row.color,
                      flex: 1,
                      overflow: "hidden",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {/* Slice the string based on rp for a typewriter feel */}
                    {row.value.slice(
                      0,
                      Math.round(interpolate(rp, [0, 1], [0, row.value.length]))
                    )}
                    {rp < 0.98 && (
                      <span
                        style={{
                          display: "inline-block",
                          width: 2,
                          height: 28,
                          backgroundColor: row.color,
                          marginLeft: 4,
                          verticalAlign: "middle",
                          opacity: Math.sin(frame * 0.5) > 0 ? 1 : 0,
                        }}
                      />
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </AbsoluteFill>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

