            flexDirection: "column",
            alignItems: "center",
            gap: 20,
          }}
        >
          {/* Pulsing ring */}
          <div
            style={{
              position: "relative",
              width: 180,
              height: 180,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {/* Outer glow ring */}
            <div
              style={{
                position: "absolute",
                width: 180,
                height: 180,
                borderRadius: "50%",
                border: `2px solid ${COLORS.teal}`,
                opacity: glowPulse * llmProgress * 0.35,
                transform: `scale(${1 + (1 - glowPulse) * 0.18})`,
              }}
            />
            <div
              style={{
                width: 130,
                height: 130,
                borderRadius: "50%",
                background: `radial-gradient(circle, rgba(0,212,170,0.18) 0%, rgba(0,212,170,0.04) 100%)`,
                border: `2px solid rgba(0,212,170,0.5)`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <span style={{ fontSize: 44, fontWeight: 800, color: COLORS.teal }}>AI</span>
            </div>
          </div>
          <div style={{ fontSize: 26, fontWeight: 600, color: COLORS.muted, letterSpacing: "0.08em" }}>
            Perfect Format for Analysis
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

