// ─── Composition ─────────────────────────────────────────────────────────

// Timestamps → frames (at 25fps, hh:mm:ss:ff)
// S1:  00:00:00:00 → 00:00:02:04  = 54 frames
// S2:  00:00:02:04 → 00:00:05:18  = 89 frames
// S3:  00:00:06:00 → 00:00:09:24  = 99 frames
// S4:  00:00:09:24 → 00:00:15:10  = 136 frames
// S5:  00:00:16:01 → 00:00:19:06  = 80 frames
// S6:  00:00:19:16 → 00:00:22:12  = 71 frames
// S7:  00:00:22:12 → 00:00:26:11  = 99 frames
// S8:  00:00:26:16 → 00:00:31:04  = 113 frames
// S9:  00:00:31:04 → 00:00:34:06  = 77 frames
// S10: 00:00:34:06 → 00:00:37:09  = 78 frames

const S1  =  54;
const S2  =  89;
const S3  =  99;
const S4  = 136;
const S5  =  80;
const S6  =  71;
const S7  =  99;
const S8  = 113;
const S9  =  77;
const S10 =  78;

const SCENES = [S1, S2, S3, S4, S5, S6, S7, S8, S9, S10];
const TOTAL_SEQUENCES = SCENES.reduce((a, b) => a + b, 0) + SCENES.length * TRANSITION;
const TOTAL_TRANSITIONS = (SCENES.length - 1) * TRANSITION;

export const durationInFrames = TOTAL_SEQUENCES - TOTAL_TRANSITIONS;

const MainComposition: React.FC = () => {
  const scenes = [
    <Scene1  />, <Scene2  />, <Scene3  />, <Scene4  />,
    <Scene5  />, <Scene6  />, <Scene7  />, <Scene8  />,
    <Scene9  />, <Scene10 />,
  ];

  return (
    <TransitionSeries>
      {scenes.map((scene, i) => (
        <React.Fragment key={i}>
          <TransitionSeries.Sequence durationInFrames={SCENES[i] + TRANSITION}>
            {scene}
          </TransitionSeries.Sequence>
          {i < scenes.length - 1 && (
            <TransitionSeries.Transition
              presentation={fade()}
              timing={linearTiming({ durationInFrames: TRANSITION })}
            />
          )}
        </React.Fragment>
      ))}
    </TransitionSeries>
  );
};

export default MainComposition;
